window.RP_SESSION={"id":"S-807cd7383666","messages":[{"id":"RP-II-0097806","time":"2026-05-06T18:34:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097807","time":"2026-05-06T18:35:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"엘라의 장례식은 조톨하다면 조촐하다고 할 수도 있고 그렇지 않다면 그렇지 않다고도 할 수 있었다.\n\n왕국군에서 찾아온 것은 그녀의 상관이었던 라나 3보급관과 그녀와 친하게 지내던 병사 넷. 총 다섯과 어설픈 용맹의 길드원들 뿐이었다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097808","time":"2026-05-06T18:35:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"어설픈 용맹의 길드원들은 길드 뒷켠 들판에 모여 그녀를 기리고 있었다. 누군가는 아직 믿을 수 없다는 얼굴을 하고, 누군가는 말없이 고개를 숙이고. 평소라면 왁자지껄 시끄러울 길드가 이상할정도로 조용했다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097809","time":"2026-05-06T18:36:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"라르손도 조용하게 고개숙이고 앉아있읍니다.\n\n\"오늘은 무지개가 뜨겠구먼...\"","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097810","time":"2026-05-06T18:36:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"그 가운데 흰 천이 덮인 관이 놓여있었다. 관 위에는 엘라가 쓰던 활과 화살통이 올려져 있었다. 그녀의 작은 체구에 맞게 장난감처럼 작았지만 분명 길드원들은 그 물건의 무게를 알고 있을 터였다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097811","time":"2026-05-06T18:36:00+09:00","room":"RP II","name":"숀 카리엔 / 머챈트","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" ... \"","characters":["P-5c88d36f51cd","P-ecd21af3262f"]},{"id":"RP-II-0097812","time":"2026-05-06T18:37:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"3보급관 라나는 정복을 입고서 관 앞에 섰다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097813","time":"2026-05-06T18:37:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"왕국군 2번 선봉대 3보병대 8중대 소속 궁병 엘라.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097814","time":"2026-05-06T18:38:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-79263e0865dd"]},{"id":"RP-II-0097815","time":"2026-05-06T18:38:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그녀는 전장에서 빠른 발이라 불렸고 숲에서 그녀의 실력을 부정할 자는 아무도 없었다. 하지만 상관의 입장으로 보건데 제법 시끄러운 골치거리였다.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097816","time":"2026-05-06T18:38:00+09:00","room":"RP II","name":"스노우 글로우","profile":"시안 던 브링어","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n만나본적이 없는 이였지만, 어제 션과의 만남으로 그녀가 죽었음을 전해들었기때문에, 그녀 역시 장례에 참가한다. 한번도 본 적 없는 그녀이지만, 가는길만큼은 편안하길. 바래본다.","characters":["P-2bd2e06457e6"]},{"id":"RP-II-0097817","time":"2026-05-06T18:38:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"라나는 잠시 침묵을 하고서 이야기를 이어갔다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097818","time":"2026-05-06T18:38:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"...\"","characters":[]},{"id":"RP-II-0097819","time":"2026-05-06T18:39:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"하지만 그녀는 동료를 위하고 사람을 챙기고 버틸 때와 놓을 때를 알아가는 어찌보면 가장 군인다운 군인이었다.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097820","time":"2026-05-06T18:39:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"라나는 엘라의 관 위에 하얀 꽃 한송이를 올려뒀다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097821","time":"2026-05-06T18:40:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"전역하고도 제법 시끄럽게 살았구나.\"\n\n라나는 주변을 한번 둘러보고서 이야기했다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097822","time":"2026-05-06T18:40:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"고생했다.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097823","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"라나는 뒤로 잠시 물러섰고 그녀의 뒤에는 그녀를 따라온 군인들이 열을 맞춰 서 있었다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097824","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"전원!\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097825","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"고 엘라 궁병에게!\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097826","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"경례!\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097827","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"척!","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097828","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"격식에 맞는 경례소리.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097829","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"그러고 잠시 시간이 지나고","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097830","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"바로!\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097831","time":"2026-05-06T18:41:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"척!","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097832","time":"2026-05-06T18:42:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"여기까지입니다. 감사합니다. 어설픈 용맹. 저희가 동료를 애도할 자리를 만들어줘서.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097833","time":"2026-05-06T18:42:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"라나는 그렇게 말하고서 자리를 비켜줬다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097834","time":"2026-05-06T18:43:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"스텔라는 라나가 자리를 비키고서 관 앞에 섰다. 그리고 잠시 뜸을 들이더니...","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097835","time":"2026-05-06T18:43:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"엘라는....\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097836","time":"2026-05-06T18:43:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"솔직히 말해서 조용한 사람은 아니었죠?\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097837","time":"2026-05-06T18:44:00+09:00","room":"RP II","name":"테론 이스트가드","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"엘라 씨...\"","characters":["P-f7fa038766bf"]},{"id":"RP-II-0097838","time":"2026-05-06T18:45:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"모나는 가볍게 지팡이를 톡톡 바닥에 두들기고는 엘라의 관 주변에 꽃을 피워냅니다. 그 꽃에 엘라의 영혼이 깃들기를 빌면서.. 그리고 나중에 그 꽃잎이 바람에 실려 저 하늘 위의 별이 될 수 있도록..","characters":["P-48cca58d02b2"]},{"id":"RP-II-0097839","time":"2026-05-06T18:45:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"입도 거칠고, 성질도 급하고, 가끔 이상한 말도 하고.... 그래도 어느샌가 익숙해져서 저희와 함께 있고...\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097840","time":"2026-05-06T18:45:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"그렇다네. 언제나 소란속에 있고, 요란하게 노는 친구였지!\"","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097841","time":"2026-05-06T18:46:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\".. 이리 이별할 줄 알았더라면... 말이라도 걸어볼 한번 걸 그랬네요.. \"","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0097842","time":"2026-05-06T18:46:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"그래도... 함께해서 좋았어요.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097843","time":"2026-05-06T18:46:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"솔직히 같이 의뢰 한번 다녀온게 전부였지만... 그래도 같은 건물에서 지내던 동료의 부고는 마음이 울컥하지 않을 수 없었습니다","characters":["P-79263e0865dd"]},{"id":"RP-II-0097844","time":"2026-05-06T18:46:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"엘라와 다툰 사람, 웃은 사람, 서로 장난을 치고, 슬쩍 챙김을 받고...\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097845","time":"2026-05-06T18:46:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"모두 그런 엘라를 기억해줄거라고 믿어요.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097846","time":"2026-05-06T18:46:00+09:00","room":"RP II","name":"스노우 글로우","profile":"시안 던 브링어","identity":"reviewed","type":"dialogue","body":"\" ...저는 그분을 만난적이 없지만. 그래도, 잘 가셨으면, 하는 바람으로 왔어요. \"","characters":["P-2bd2e06457e6"]},{"id":"RP-II-0097847","time":"2026-05-06T18:47:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"언젠가 영혼길너머서 다시만난다면...\"","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097848","time":"2026-05-06T18:47:00+09:00","room":"RP II","name":"테론 이스트가드","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"엘라 씨 태우고 갈 곳이 많은데..\"","characters":["P-f7fa038766bf"]},{"id":"RP-II-0097849","time":"2026-05-06T18:47:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"못받은 맥주값은 그때 받겠네, 친구여!\"","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097850","time":"2026-05-06T18:48:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"밥 한그릇 얻어먹고, 흰 꽃과 동전 하나 올려둔채 자리를 떠납니다","characters":["P-79263e0865dd"]},{"id":"RP-II-0097851","time":"2026-05-06T18:48:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"아직 실감이 나지 않는 사람도 있을거에요. 저도 그래요. 식당에 내려가면 의자에 불량하게 앉고서 심심하게 있는 그녀가 모카에게서 도망치는 모습이 보일 것 같아요.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097852","time":"2026-05-06T18:48:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"하지만, 죽은 사람은 죽은 사람이에요. 이제 보내줘야해요.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097853","time":"2026-05-06T18:48:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"존이 자기의 전재산을 엘라의 장례식에 기부했어...!","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097854","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"흑흑","characters":["P-79263e0865dd"]},{"id":"RP-II-0097855","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"하지만! 그렇다고 해서 엘라가 사라지는 것은 아닙니다!\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097856","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"모카한테서 털은 제가 찾아올게요...\"\n\n꽃과 발모제를 고이 놓아둡니다.","characters":[]},{"id":"RP-II-0097857","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"존","profile":"존","identity":"reviewed","type":"dialogue","body":"큰마음 먹었다","characters":["P-79263e0865dd"]},{"id":"RP-II-0097858","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"자툴라님이 눈을 뜨는 그날. 대자연 속에서 다시 만나요, 엘라 씨.\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0097859","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"엘라는. 저희의 길드와 같이 남을거에요.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097860","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"엘라, 고마웠어요.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097861","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그렇게 새로운 순환의 길에 접어든 그녀를 배웅합니다.","characters":["P-48cca58d02b2"]},{"id":"RP-II-0097862","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"스텔라는 엘라의 관 위에 어설픈 용맹의 심볼을 올려뒀습니다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097863","time":"2026-05-06T18:49:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"모두, 마지막 인사를 남기길 바래요.\"","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097864","time":"2026-05-06T18:50:00+09:00","room":"RP II","name":"발린 호프","profile":"발린 호프","identity":"unresolved","type":"dialogue","body":"\"...하아...금방 다시 만나자 나도 걷 그쪽으로 갈테니깐\"","characters":[]},{"id":"RP-II-0097865","time":"2026-05-06T18:50:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"그러고선 자리를 비켰습니다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097866","time":"2026-05-06T18:50:00+09:00","room":"RP II","name":"숀 카리엔 / 머챈트","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"머챈트가 '뭐라도 말 좀 해' 라며 숀의 등을 툭 밀었습니다.\n\n잠깐 딴 생각을 하던 숀은 그만 한 발자국 걸어나오게 되었습니다.\n\n\" 어... \"\n\n집중된 시선.\n\n\" ...음. \"\n\n입이 바짝 마릅니다.,","characters":["P-5c88d36f51cd","P-ecd21af3262f"]},{"id":"RP-II-0097867","time":"2026-05-06T18:51:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 가시는 길에 외롭지 않기를.. \"\n\n 관 위에 하얀 꽃 한 송이를 두고 잠시 고개 숙여 묵념합니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0097868","time":"2026-05-06T18:51:00+09:00","room":"RP II","name":"숀 카리엔 / 머챈트","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\n\" 엘라는... 그러니까...\n\n데미간이었습니다. 그녀도...\n\n나 처럼 털이...\n\n그니깐은... 음. \"\n\n꼴깍ᆢ.\n\n\" 흰 털을 지닌... 토, 토끼 데미간이었고. 활을... 쐈죠. ...우리의 후장... 아니 그니까, 후방. 그래요 후방... 에서... \"\n\n누군가 쿡, 하고 웃습니다.\n숀도 그 웃음을 들었을겁니다.\n창피함은 분노로 바뀝니다.\n\n하지만 여긴 화를 낼 장소가 아닙니다.\n숀도 알고 있습니다.\n\n그는 떠뜸떠뜸... 다시 말을 시작합니다.\n\nᆢ그리고ᆢ.\n\n\" 솔직히 말하면 잘 모릅니다. 그녀가 나와 같은 데미간이었고. 털을 지녔고. 활을 쐈어요. \n\n엘라가 여기에서 무슨 일을 했는쥐는 얘기로만 종종 전해들었죠. 대부분 지나가는 얘기를 듣게 된 거쥐만요.\n\n그러다 하루는 문득, 훈련장에서 엘라가 활을 쏘는 모습을 봤는데 나쁘쥐 않았습니다.\n\n저런 녀석에게 후방을 맡기면, 믿음직스럽겠다- 하고 생각이 들었죠.\n\n그래요. 그랬을 겁니다.\n\n비록 이번엔 살아돌아오지 못했쥐","characters":["P-5c88d36f51cd","P-ecd21af3262f"]},{"id":"RP-II-0097869","time":"2026-05-06T18:51:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"\"엘라여, 북풍거인 자단이 자네를 찾을걸세!\"","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097870","time":"2026-05-06T18:53:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" .... \"\n\n 숀의 연설에 고개를 끄덕입니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0097871","time":"2026-05-06T18:54:00+09:00","room":"RP II","name":"숀 카리엔 / 머챈트","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그러니까... 내가 하고싶은 말은... \"\n\n숀이 다시 한 번 침을 삼켰습니다.\n\n얘기를 이어하고나니, 마음이 조금 편합니다.\n\n\" ... 어쩌면, 좋은 친구가 됐었겠다. 라는 거에요.\n\n그리고 지금 이 자리에, 곁에 있쥐만 말 한 번 섞어본 적 없는 친구들도요. \"","characters":["P-5c88d36f51cd","P-ecd21af3262f"]},{"id":"RP-II-0097872","time":"2026-05-06T18:57:00+09:00","room":"RP II","name":"숀 카리엔 / 머챈트","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"숀은 자신의 입가에서 희고 검은 수염 하나를 뽑았습니다.\n\n그리고 엘라의 관 앞에 내려놓았습니다.\n\n\" ... 털 지닌 인간이여. 이제 자연의 품으로 돌아가라. \"\n\n데미간의 풍습대로요.","characters":["P-5c88d36f51cd","P-ecd21af3262f"]},{"id":"RP-II-0097873","time":"2026-05-06T18:57:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"뒤에 서 있던 션이 무릎을 굽혀 숀의 어깨를 두드려주었습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0097874","time":"2026-05-06T18:57:00+09:00","room":"RP II","name":"아리차","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"아리차는 묵묵히 장례식을 지켜봅니다. 오늘 또 하나의 동료가 죽었습니다.\n\n하지만 이는 일상과도 같은 일. 위험한 일을 하면서 모두가 언제까지고 하하 호호 오랫동안 행복하게 살았습니다, 같은 결말은 처음부터 바라지 않았습니다.\n\n언젠가는 분명, 자신의 차례가 돌아오는 날도 있겠죠. 단지 그것이 오늘이 아닐 뿐.","characters":["P-0322eff604c2"]},{"id":"RP-II-0097875","time":"2026-05-06T18:58:00+09:00","room":"RP II","name":"스노우 글로우","profile":"시안 던 브링어","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n그녀는 모르는 사람의 장례에서도 슬픔을 느꼈는데, 아는사람이 죽었다는 사실을 확인할수 있을까라는 상념에 빠졌다. 하지만, 그주제는 장례이후 방에서 스스로 생각해볼 문제이리라 다잡으며, 그녀를 추모하지.","characters":["P-2bd2e06457e6"]},{"id":"RP-II-0097876","time":"2026-05-06T18:59:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"미샤도 아카쿠고 나지막히 인사를 한번 올리고 물러섰습니다.\n\n카카투 방식대로 두 손을 높게 올리고 고개를 낮춘 아카쿠.\n작게 인사를 올린 미샤.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097877","time":"2026-05-06T19:00:00+09:00","room":"RP II","name":"숀 카리엔 / 머챈트","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"그러자 그 모습을 지켜보던 머챈트도, 자신의 가죽 힙쌕에서 쪽가위를 꺼내 머리카락을 몇가닥을 잘랐습니다.\n\n그녀는 한 쪽 무릎을 꿇고 애도하는 숀에게 윙크하며 앉아 자른 머리카락을 내려 놓았습니다.\n\n\" 자연으로... 돌아가라. \"","characters":["P-5c88d36f51cd","P-ecd21af3262f"]},{"id":"RP-II-0097878","time":"2026-05-06T19:00:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"봄꽃이 피면 여름이 다가와 비바람 내리는 법. 엘라 그대는 모질게도 봄 되는 계절에 우리를 남겨두고 작별해버렸군.\"\n\n션이 반짝이는 실링 두 푼을 관 앞에 내려놓았습니다.\n\n\"그대의 눈 감음은 하늘 아래에 비극이나 지극히 높은 존재의 품 안에 드는 지복이라. 생명을 결정지음에 예정된 순리이니 슬퍼하지 않겠네.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0097879","time":"2026-05-06T19:00:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"자신의 수염을뽑아 똑같이 내려놓읍니다.","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097880","time":"2026-05-06T19:00:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"\"죽음은.. 역시 익숙하지 않다. 해가 뜨는 곳. 죽은 자의 세상에서 본다. 작은 토끼.\"\n\n코난은 덤덤하게 말하고서 물러납니다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097881","time":"2026-05-06T19:01:00+09:00","room":"RP II","name":"아리차","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그래도 인사를 남기는 동료들 틈바구니에 섞여 묵묵히 자신의 차례를 기다립니다.\n\n그러다 자신의 차례가 왔을 때. 금화 한 닢으로 노크하듯 관을 통통 두드리곤, 그 위에 놓습니다.\n\n\"잘 가, 족발토끼.\"\n\n그리곤 미련없이 돌아섭니다.","characters":["P-0322eff604c2"]},{"id":"RP-II-0097882","time":"2026-05-06T19:01:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"드워프에게 수염이란...","characters":["P-b551ad21c43a"]},{"id":"RP-II-0097883","time":"2026-05-06T19:01:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"그렇게 모든 길드원들의 인사가 끝나고 모두들 그녀를 기리기 위한 시간을 가집니다. 속 마음으로 각자 무슨 생각을 할까요? 하나 확실한건 모두 엘라를 위하는 생각을 하고 있다는 것이네요.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097884","time":"2026-05-06T19:02:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"서늘한 바람이 산들산들 불어옵니다.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097885","time":"2026-05-06T19:02:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"약간은 짓궂지만 따스한 마치 엘라같은 바람이네요.","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097886","time":"2026-05-06T19:03:00+09:00","room":"RP II","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"unresolved","type":"dialogue","body":"족발 찌질이 베이비들. 폼 잡기는.\n\n웃어!","characters":[]},{"id":"RP-II-0097887","time":"2026-05-06T19:03:00+09:00","room":"RP II","name":"테론 이스트가드","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"스마일","characters":["P-f7fa038766bf"]},{"id":"RP-II-0097888","time":"2026-05-06T19:03:00+09:00","room":"RP II","name":"진행 / 라나 / 스텔라 / 미샤 / 아카쿠 / 코난","profile":"스텔라 스타라이트","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e6655a038328","P-41ba4c5736e6","P-96ab98d2591c","P-96ee3cc09ac8"]},{"id":"RP-II-0097889","time":"2026-05-06T19:03:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
